const DAILY_TRACKING_YML_TEMPLATE = `# AcademicFlow daily tracking workflow
name: Daily Tracking

on:
  workflow_dispatch:
    inputs:
      plan_id:
        description: '立即试跑的计划 id（留空 = 常规立即追踪）'
        required: false
        type: string
__TRACKING_SCHEDULE_BLOCK__

jobs:
  track:
    runs-on: ubuntu-latest
    # 追踪结果要靠 git push 落回仓库，默认 GITHUB_TOKEN 只读会 403
    # （remote: Write access to repository not granted），必须显式申请写权限
    permissions:
      contents: write
    steps:
      - name: Checkout workspace
        uses: actions/checkout@v4

      - name: Setup Python
        uses: actions/setup-python@v5
        with:
          python-version: '3.11'

      - name: Install dependencies
        run: |
          pip install requests

      - name: Run daily tracking
        env:
          GITHUB_TOKEN: \${{ secrets.GITHUB_TOKEN }}
          # 触发源：schedule → 走「定时计划」路径；workflow_dispatch → 走「立即追踪」路径
          TRIGGER_EVENT: \${{ github.event_name }}
          # workflow_dispatch 可带 plan_id：非空 → 立即试跑该计划（一次性，不写 last_run_date）
          TRIGGER_PLAN_ID: \${{ github.event.inputs.plan_id }}
        run: |
          python .github/scripts/daily_tracking.py

      - name: Commit and push if changes
        run: |
          git config user.name "academicflow-bot"
          git config user.email "bot@academicflow.local"
          if [ -n "$(git status --porcelain)" ]; then
            git add -A
            git commit -m "chore: daily tracking - \$(date +%Y-%m-%d)"
            git push
            echo "Tracking results committed and pushed."
          else
            echo "No changes from daily tracking."
          fi
`

/**
 * 渲染 daily-tracking.yml 的 schedule（按启用计划实际用到的「日子 + 时刻」动态排 cron）。
 *
 * crons 为 UTC 的**完整 5 段 cron**（来自 planCronSpecs，已去重、已排序）；
 * 传空数组 = 没有任何启用的定时计划 → **整个 schedule 键都不写出**（零调度、零空跑）。
 *
 * 为什么空计划时连 schedule 键都要删掉：GitHub Actions 的 schedule 必须是**非空序列**。
 * 之前这里空计划时写成 `schedule:` 只跟一行注释（求值为 null），被 GitHub 判为
 * **非法 workflow**（`schedule section must be sequence node but got scalar node with "!!null" tag`）
 * —— 该 workflow 会以「文件路径」为名注册，且**每次 push 都开一个 0 秒失败 run**，
 * 于是每次同步（多次 push）都发一封 "workflow were not run" 邮件。所以无计划 = 不写 schedule 键。
 * 注意 `schedule: []` 同样非法（空序列），只能整个省略。
 *
 * 为什么不写死固定 cron：固定每日拉起会让「今天没有任何计划到期」的日子也白跑一个 job，
 * 白烧 Actions 额度。动态 cron 把「日」（每周星期几 / 每月几号）也排进去，
 * 让 monthly / weekly 计划只在真正需要的日子触发；是否真跑，再由脚本内的
 * 到期探针（is_plan_due）二次判断——探针不通过就直接退出、不发任何网络请求。
 */
export function buildDailyTrackingYml(crons: string[]): string {
  const block = crons.length
    ? `  schedule:\n${crons.map((c) => `    - cron: '${c}'`).join('\n')}`
    : ''
  return DAILY_TRACKING_YML_TEMPLATE.replace('__TRACKING_SCHEDULE_BLOCK__', block)
}

/** 默认（无计划）版本：仓库初始化 / 重装后端时写入，随后由前端按计划重写 */
export const DAILY_TRACKING_YML = buildDailyTrackingYml([])

const DAILY_TRACKING_SCRIPT = `#!/usr/bin/env python3
"""
AcademicFlow Daily Tracking Script
-------------------------------------------------
从 keyword_groups/keyword_groups.csv 读取关键词组、
从 journals/journal_tracking.csv 读取期刊追踪列表，
调用 OpenAlex API 搜索近 7 天的新文献。

**筛选制**：命中的文献**不再直接进文献库**，而是写成「候选」——
写进 tracking/inbox.csv（status=pending），由用户在追踪页逐条裁决
（入库 / 忽略）。同时写一份 logs/tracking/{date}.md 报告。

去重口径 = 已入库的（literatures.csv）∪ 候选表里的**全部行**（含已忽略）。
这样"忽略"过的文献不会在第二天又被重新命中。

期刊追踪按 ISSN 精确检索（OpenAlex works 的 primary_location.source.issn）。
期刊行没填 ISSN 时，先用刊名到 OpenAlex /sources 反查一次拿 ISSN ——
用户往往不知道期刊的准确著录名，这一步保证他填的 "Nature" 也能被追踪。
"""

import csv
import os
import re
import sys
import time
import xml.etree.ElementTree as ET
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from datetime import datetime, timedelta
from email.utils import parsedate_to_datetime
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent.parent.parent
LITERATURES_CSV = BASE_DIR / "literatures" / "literatures.csv"
KEYWORD_GROUPS_CSV = BASE_DIR / "keyword_groups" / "keyword_groups.csv"
JOURNALS_CSV = BASE_DIR / "journals" / "journal_tracking.csv"
INBOX_CSV = BASE_DIR / "tracking" / "inbox.csv"
PLANS_CSV = BASE_DIR / "tracking" / "plans.csv"
LOGS_DIR = BASE_DIR / "logs" / "tracking"

OPENALEX_API = "https://api.openalex.org/works"
OPENALEX_SOURCES_API = "https://api.openalex.org/sources"
USER_AGENT = "AcademicFlow/1.0 (mailto:bot@academicflow.local)"
# 抓取并发度：多个计划 / 期刊同时抓，降低墙钟时间（省 Actions 时长）。
# 4 路足够压住等待，又低于 OpenAlex 礼貌池 10 req/s 的限速，避免被限流。
MAX_FETCH_WORKERS = 4


def load_keyword_groups():
    """从 CSV 加载启用的关键词组"""
    groups = []
    if not KEYWORD_GROUPS_CSV.exists():
        print(f"[WARN] 关键词组文件不存在: {KEYWORD_GROUPS_CSV}")
        return groups

    with open(KEYWORD_GROUPS_CSV, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            if row.get("enabled", "").lower() in ("true", "1", "yes"):
                groups.append({
                    "id": row.get("group_id", ""),
                    "name": row.get("group_name", ""),
                    "expression": row.get("expression", ""),
                    "translate_abstract": row.get("translate_abstract", "").lower() in ("true", "1", "yes"),
                })
    return groups


def _read_journals_raw():
    """读 journals/journal_tracking.csv 的全部行（不按 enabled 过滤）"""
    journals = []
    if not JOURNALS_CSV.exists():
        print(f"[WARN] 期刊追踪文件不存在: {JOURNALS_CSV}")
        return journals

    with open(JOURNALS_CSV, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            journals.append({
                "id": row.get("id", ""),
                "name": (row.get("name", "") or "").strip(),
                "issn": (row.get("issn", "") or "").strip(),
                "rss_url": (row.get("rss_url", "") or "").strip(),
                "enabled": row.get("enabled", "").strip().lower() in ("true", "1", "yes"),
            })
    return journals


def load_journals():
    """立即追踪用：仅「已启用」的期刊（rss_url 允许为空）"""
    return [j for j in _read_journals_raw() if j["enabled"]]


def load_all_journals():
    """定时计划用：按 id 索引**全部**期刊。
    计划里的期刊是显式选择（计划本身即用户意图），不再受全局启用开关影响。"""
    return {j["id"]: j for j in _read_journals_raw() if j["id"]}


# 计划表列契约（必须与前端 src/services/trackingPlanData.ts 的
# TRACKING_PLAN_HEADERS 逐字一致、顺序一致；新列一律追加在末尾）
# interval ∈ daily|weekly|semimonthly|monthly；semimonthly = 每月月初 1 日 + 月中 15 日。
PLAN_HEADERS = [
    "plan_id", "plan_name", "enabled", "interval", "hour", "minute",
    "weekdays", "day_of_month", "journal_ids", "expression",
    "translate_abstract", "last_run_date", "created_at",
]


def _safe_int(v, lo, hi, default):
    try:
        n = int(str(v).strip())
    except (TypeError, ValueError):
        return default
    return min(max(n, lo), hi)


def _split_ids(v):
    return [x for x in re.split(r"[,\\s]+", (v or "").strip()) if x]


def _read_plans_raw():
    """读 tracking/plans.csv 的全部计划（**不按 enabled 过滤**）"""
    plans = []
    if not PLANS_CSV.exists():
        return plans
    with open(PLANS_CSV, "r", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            weekdays = [int(x) for x in _split_ids(row.get("weekdays")) if x.isdigit()]
            plans.append({
                "plan_id": (row.get("plan_id", "") or "").strip(),
                "plan_name": (row.get("plan_name", "") or "").strip(),
                "enabled": (row.get("enabled", "") or "").strip().lower() in ("true", "1", "yes"),
                "interval": (row.get("interval", "") or "daily").strip() or "daily",
                "hour": _safe_int(row.get("hour"), 0, 23, 9),
                "minute": _safe_int(row.get("minute"), 0, 59, 0),
                "weekdays": weekdays,
                "day_of_month": _safe_int(row.get("day_of_month"), 1, 28, 1),
                "journal_ids": _split_ids(row.get("journal_ids")),
                "expression": (row.get("expression", "") or "").strip(),
                "translate_abstract": (row.get("translate_abstract", "") or "").strip().lower() in ("true", "1", "yes"),
                "last_run_date": (row.get("last_run_date", "") or "").strip(),
            })
    return plans


def load_plans():
    """加载「启用」的定时追踪计划（结构化）"""
    return [p for p in _read_plans_raw() if p["enabled"]]


def load_plan_by_id(plan_id):
    """立即试跑用：按 id 取单个计划，**不过滤 enabled**（可先试后启用）"""
    for p in _read_plans_raw():
        if p["plan_id"] == plan_id:
            return p
    return None


def write_plans_last_run(ran):
    """把本次真正执行过的计划的 last_run_date 回写为北京当天（用于当天防重）。
    ran = {plan_id: 'YYYY-MM-DD'}；原地重写 plans.csv，保留其它列原值。"""
    if not ran or not PLANS_CSV.exists():
        return
    with open(PLANS_CSV, "r", encoding="utf-8") as f:
        rows = list(csv.DictReader(f))
        fieldnames = list(rows[0].keys()) if rows else PLAN_HEADERS
    for row in rows:
        pid = (row.get("plan_id", "") or "").strip()
        if pid in ran:
            row["last_run_date"] = ran[pid]
    with open(PLANS_CSV, "w", encoding="utf-8", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        for row in rows:
            writer.writerow(row)
    print(f"[INFO] 已回写 {len(ran)} 个计划的 last_run_date")


def resolve_issn_by_name(name):
    """期刊行缺 ISSN 时，用刊名到 OpenAlex /sources 反查最可能一本的 ISSN。
    拿不到就返回空串——宁可这次不追踪，也不拿一本不相干的刊的 ISSN 去搜。"""
    params = {
        "search": name,
        "filter": "type:journal",
        "per-page": 1,
        "select": "display_name,issn_l,issn",
    }
    try:
        resp = requests.get(OPENALEX_SOURCES_API, params=params,
                            headers={"User-Agent": USER_AGENT}, timeout=30)
        resp.raise_for_status()
        results = resp.json().get("results", [])
        if not results:
            return ""
        src = results[0]
        issns = src.get("issn") or []
        return (src.get("issn_l") or (issns[0] if issns else "") or "").strip()
    except Exception as e:
        print(f"[ERROR] 反查期刊 ISSN 失败 '{name}': {e}")
        return ""


def load_seen_dois():
    """去重口径 = 已入库(文献库) ∪ 候选表全部行(含已忽略的)"""
    dois = set()
    for path in (LITERATURES_CSV, INBOX_CSV):
        if not path.exists():
            continue
        with open(path, "r", encoding="utf-8") as f:
            reader = csv.DictReader(f)
            for row in reader:
                doi = (row.get("doi") or "").strip().lower()
                if doi:
                    dois.add(doi)
    return dois


def search_openalex(keyword, from_date, to_date, per_page=50):
    """调用 OpenAlex API 搜索文献"""
    params = {
        "search": keyword,
        "filter": f"from_publication_date:{from_date},to_publication_date:{to_date}",
        "per-page": per_page,
        "sort": "publication_date:desc",
    }
    headers = {"User-Agent": USER_AGENT}

    try:
        resp = requests.get(OPENALEX_API, params=params, headers=headers, timeout=30)
        resp.raise_for_status()
        data = resp.json()
        return data.get("results", [])
    except Exception as e:
        print(f"[ERROR] OpenAlex search failed for '{keyword}': {e}")
        return []


def search_openalex_journal(issn, from_date, to_date, per_page=50):
    """按期刊 ISSN 精确检索近 N 天的新文献"""
    filter_str = (
        f"primary_location.source.issn:{issn},"
        f"from_publication_date:{from_date},to_publication_date:{to_date}"
    )
    params = {
        "filter": filter_str,
        "per-page": per_page,
        "sort": "publication_date:desc",
    }
    headers = {"User-Agent": USER_AGENT}

    try:
        resp = requests.get(OPENALEX_API, params=params, headers=headers, timeout=30)
        resp.raise_for_status()
        return resp.json().get("results", [])
    except Exception as e:
        print(f"[ERROR] OpenAlex journal search failed for ISSN '{issn}': {e}")
        return []


# ============================================================
# 期刊 RSS/Atom：追踪时**优先用 RSS**，无 feed / 失败再退回 OpenAlex
# ============================================================
DOI_RE = re.compile(r'10\\.\\d{4,9}/[^\\s"\'<>]+')


def _local(tag):
    return tag.split("}")[-1].lower()


def _child_text(node, *names):
    """取第一个「局部名命中且文本非空」的直接子节点文本（兼容 RSS/Atom 命名空间）"""
    for child in list(node):
        if _local(child.tag) in names and (child.text or "").strip():
            return child.text.strip()
    return ""


def _rss_author(node):
    for child in list(node):
        name = _local(child.tag)
        if name in ("creator", "author"):
            txt = (child.text or "").strip()
            if txt:
                return txt
            for sub in list(child):
                if _local(sub.tag) == "name" and (sub.text or "").strip():
                    return sub.text.strip()
    return ""


def _rss_link(node):
    for child in list(node):
        if _local(child.tag) != "link":
            continue
        href = (child.get("href") or "").strip()
        if href:
            return href
        if (child.text or "").strip():
            return child.text.strip()
    return ""


def _parse_rss_date(raw):
    raw = (raw or "").strip()
    if not raw:
        return None
    try:
        return parsedate_to_datetime(raw)
    except Exception:
        pass
    try:
        return datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except Exception:
        return None


def _extract_doi(text):
    m = DOI_RE.search(text or "")
    return m.group(0).rstrip(".,;").lower() if m else ""


def _strip_html(text):
    return re.sub(r"<[^>]+>", " ", text or "").strip()


def fetch_rss_papers(rss_url, from_date):
    """抓期刊 RSS/Atom，返回 (papers, ok)。
    ok=False 表示「这条 feed 不可用」，由调用方退回 OpenAlex。
    没有 DOI 的条目一律跳过——去重与裁决都依赖 DOI，宁可少收也不猜。"""
    try:
        resp = requests.get(rss_url, headers={"User-Agent": USER_AGENT}, timeout=30)
        resp.raise_for_status()
        root = ET.fromstring(resp.content)
    except Exception as e:
        print(f"[WARN] RSS 抓取失败 {rss_url}: {e}")
        return [], False

    nodes = root.findall(".//item") or root.findall(".//{http://www.w3.org/2005/Atom}entry")
    feed_title = _child_text(root.find(".//channel"), "title") if root.find(".//channel") is not None else ""
    if not feed_title:
        feed_title = _child_text(root, "title")

    papers = []
    for node in nodes:
        title = _child_text(node, "title")
        if not title:
            continue
        link = _rss_link(node)
        pub = _parse_rss_date(_child_text(node, "pubdate", "published", "updated", "date"))
        if pub is not None:
            try:
                if pub.strftime("%Y-%m-%d") < from_date:
                    continue
            except Exception:
                pass
        desc = _child_text(node, "description", "summary", "encoded")
        doi = (_extract_doi(link)
               or _extract_doi(desc)
               or _extract_doi(_child_text(node, "doi", "identifier")))
        if not doi:
            continue
        year = pub.year if pub is not None else 0
        papers.append({
            "doi": doi,
            "title": title,
            "journal": feed_title,
            "year": str(year) if year else "",
            "authors": _rss_author(node),
            "keywords": "",
            "abstract_en": _strip_html(desc),
            "abstract_cn": "",
            "tier": "1",
            "has_graphical_abstract": "false",
            "added_at": str(int(time.time())),
            "pdf_added_at": "0",
            "source": "rss",
            "tracking_group": "",
        })
    return papers, True


def collect_journal_papers(jrn, from_date, to_date):
    """单个期刊的候选文献：**RSS 优先，无 feed / 失败再退回 OpenAlex**。
    返回 (papers, via, total_found)；via ∈ 'rss' | 'openalex' | 'none'。"""
    rss_url = (jrn.get("rss_url") or "").strip()
    if rss_url:
        papers, ok = fetch_rss_papers(rss_url, from_date)
        if ok:
            return papers, "rss", len(papers)
        print(f"[INFO] 期刊「{jrn.get('name', '')}」RSS 不可用，退回 OpenAlex")

    issn = (jrn.get("issn") or "").strip() or resolve_issn_by_name(jrn.get("name", ""))
    if not issn:
        print(f"[WARN] 无法确定 ISSN，跳过期刊: {jrn.get('name', '')}")
        return [], "none", 0
    works = search_openalex_journal(issn, from_date, to_date, per_page=200)
    return [openalex_to_literature(w, "") for w in works], "openalex", len(works)


def openalex_to_literature(work, tracking_group=""):
    """将 OpenAlex work 对象转为 Literature 行"""
    doi = (work.get("doi") or "").replace("https://doi.org/", "")
    title = work.get("title", "") or ""

    # 期刊名
    primary_loc = work.get("primary_location") or {}
    source = primary_loc.get("source") or {}
    journal = source.get("display_name", "") or ""

    # 年份
    year = work.get("publication_year", 0) or 0

    # 作者
    authorships = work.get("authorships", []) or []
    author_names = []
    for a in authorships[:10]:
        author = a.get("author") or {}
        name = author.get("display_name", "")
        if name:
            author_names.append(name)
    authors = "; ".join(author_names)
    if len(authorships) > 10:
        authors += f" et al. ({len(authorships)} authors)"

    # 关键词（从 concepts 提取）
    concepts = work.get("concepts", []) or []
    keywords = "; ".join([c.get("display_name", "") for c in concepts[:5] if c.get("display_name")])

    # 摘要
    abstract_inverted = work.get("abstract_inverted_index") or {}
    abstract_en = ""
    if abstract_inverted:
        # 从倒排索引重建摘要
        word_positions = []
        for word, positions in abstract_inverted.items():
            for pos in positions:
                word_positions.append((pos, word))
        word_positions.sort()
        abstract_en = " ".join([w for _, w in word_positions])

    now = int(time.time())

    return {
        "doi": doi,
        "title": title,
        "journal": journal,
        "year": str(year),
        "authors": authors,
        "keywords": keywords,
        "abstract_en": abstract_en,
        "abstract_cn": "",
        "tier": "1",
        "has_graphical_abstract": "false",
        "added_at": str(now),
        "pdf_added_at": "0",
        "source": "openalex",
        "tracking_group": tracking_group,
    }


# 候选表列契约（必须与前端 src/services/trackingData.ts 的
# TRACKING_INBOX_HEADERS 逐字一致、顺序一致；新列一律追加在末尾）
INBOX_HEADERS = [
    "doi", "title", "journal", "year", "authors", "keywords", "abstract_en",
    "source", "tracking_group", "found_at", "status",
]


def append_candidates(new_papers):
    """把命中的文献写成「候选」(status=pending)，**不直接进文献库**"""
    INBOX_CSV.parent.mkdir(parents=True, exist_ok=True)
    file_exists = INBOX_CSV.exists()
    now = int(time.time())
    with open(INBOX_CSV, "a", encoding="utf-8", newline="") as f:
        writer = csv.DictWriter(f, fieldnames=INBOX_HEADERS)
        if not file_exists:
            writer.writeheader()
        for paper in new_papers:
            writer.writerow({
                "doi": paper.get("doi", ""),
                "title": paper.get("title", ""),
                "journal": paper.get("journal", ""),
                "year": paper.get("year", ""),
                "authors": paper.get("authors", ""),
                "keywords": paper.get("keywords", ""),
                "abstract_en": paper.get("abstract_en", ""),
                "source": paper.get("source", "openalex"),
                "tracking_group": paper.get("tracking_group", ""),
                "found_at": str(now),
                "status": "pending",
            })


def format_candidate_lines(papers):
    """把候选文献格式化成日志里的 markdown 条目"""
    lines = ""
    for p in papers:
        doi = p["doi"] or "no-doi"
        title = p["title"] or "(无标题)"
        lines += f"- **{title}**\\n"
        lines += f"  - DOI: [{doi}](https://doi.org/{doi})\\n"
        lines += f"  - 期刊：{p.get('journal', '')}\\n"
        lines += f"  - 年份：{p.get('year', '')}\\n\\n"
    return lines


def write_log(date_str, group_results, journal_results, group_label="关键词组"):
    """写入追踪日志（立即追踪按「关键词组」、定时追踪按「计划」记）"""
    LOGS_DIR.mkdir(parents=True, exist_ok=True)
    log_path = LOGS_DIR / f"{date_str}.md"

    total_new = sum(len(r["new_papers"]) for r in group_results)
    total_new += sum(len(r["new_papers"]) for r in journal_results)

    content = f"# 追踪报告 - {date_str}\\n\\n"
    content += f"- 追踪时间（北京时间）：{_beijing_now().strftime('%Y-%m-%d %H:%M:%S')}\\n"
    content += f"- {group_label}：{len(group_results)} 个\\n"
    content += f"- 期刊：{len(journal_results)} 个\\n"
    content += f"- 新文献：{total_new} 篇\\n\\n"
    content += "---\\n\\n"

    for grp in group_results:
        content += f"## {group_label}：{grp['name']}\\n\\n"
        content += f"- 搜索表达式：\`{grp['expression']}\`\\n"
        content += f"- 检索到：{grp['total_found']} 篇\\n"
        content += f"- 新增候选：{len(grp['new_papers'])} 篇\\n\\n"

        if grp["new_papers"]:
            content += "### 新增候选（待裁决）\\n\\n"
            content += format_candidate_lines(grp["new_papers"])

    for jrn in journal_results:
        content += f"## 期刊：{jrn['name']}\\n\\n"
        if jrn.get("via") == "rss":
            content += "- 来源：RSS\\n"
            content += "- ISSN：未使用（RSS 直取）\\n"
        else:
            content += f"- ISSN：{jrn.get('issn') or '（未解析到，已跳过）'}\\n"
        content += f"- 检索到：{jrn['total_found']} 篇\\n"
        content += f"- 新增候选：{len(jrn['new_papers'])} 篇\\n\\n"

        if jrn["new_papers"]:
            content += "### 新增候选（待裁决）\\n\\n"
            content += format_candidate_lines(jrn["new_papers"])

    content += "\\n---\\n\\n*Generated by AcademicFlow Daily Tracking*\\n"

    with open(log_path, "w", encoding="utf-8") as f:
        f.write(content)

    print(f"[INFO] 日志已写入: {log_path}")


# ============================================================
# 关键词布尔表达式：AND / OR / NOT（+ 括号），本地求值
# ============================================================
# 语法（运算符须大写，与前端「标签 + 运算符下拉」的序列化一致）：
#   expr := or
#   or   := and ( OR and )*
#   and  := not ( AND? not )*      # 相邻词之间省略 AND 也视为 AND
#   not  := NOT not | atom
#   atom := '(' expr ')' | TERM
# TERM 为不含空白 / 括号 / 引号的裸词，或双引号包裹的短语。
# OpenAlex 的 search 虽也认 AND/OR/NOT，但此处一律**本地求值**，
# 以保证结果确定、不随上游分词策略漂移。


def tokenize_expression(expr):
    """把表达式切成 token：'(' / ')' / ('OP','AND'|'OR'|'NOT') / ('TERM', 文本)"""
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
            continue
        if ch == "(":
            tokens.append("(")
            i += 1
            continue
        if ch == ")":
            tokens.append(")")
            i += 1
            continue
        if ch == '"':
            j = i + 1
            buf = []
            while j < n and expr[j] != '"':
                buf.append(expr[j])
                j += 1
            tokens.append(("TERM", "".join(buf).strip()))
            i = j + 1
            continue
        j = i
        buf = []
        while j < n and (not expr[j].isspace()) and expr[j] not in '()"':
            buf.append(expr[j])
            j += 1
        word = "".join(buf)
        if word in ("AND", "OR", "NOT"):
            tokens.append(("OP", word))
        else:
            tokens.append(("TERM", word))
        i = j
    return tokens


def expression_terms(expr):
    """提取表达式里的全部关键词（仅关键词模式据此构造广搜 OR 查询）"""
    return [t[1] for t in tokenize_expression(expr) if t[0] == "TERM" and t[1]]


def build_broad_query(expr):
    """把表达式放宽成「任一词命中」的 OR 查询交给上游取超集，再本地精筛"""
    terms = expression_terms(expr)
    if not terms:
        return ""
    parts = []
    for t in terms:
        parts.append('"' + t + '"' if " " in t else t)
    return " OR ".join(parts)


def term_matches(term, text):
    """关键词在文本里按词边界匹配，多词短语允许任意空白间隔"""
    term = term.strip().lower()
    if not term:
        return False
    parts = [re.escape(w) for w in term.split()]
    core = r"\\s+".join(parts)
    if parts and parts[0][0].isalnum():
        core = r"(?<![a-z0-9])" + core
    if parts and parts[-1][-1].isalnum():
        core = core + r"(?![a-z0-9])"
    return re.search(core, text) is not None


def evaluate_expression(expr, text):
    """在 text（已小写）上按 NOT > AND > OR 求值；解析失败一律返回 False（不猜）"""
    tokens = tokenize_expression(expr)
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def parse_or():
        nonlocal pos
        val = parse_and()
        while peek() == ("OP", "OR"):
            pos += 1
            rhs = parse_and()
            val = val or rhs
        return val

    def parse_and():
        nonlocal pos
        val = parse_not()
        while True:
            tok = peek()
            if tok == ("OP", "AND"):
                pos += 1
                rhs = parse_not()
                val = rhs and val
            elif tok == "(" or tok == ("OP", "NOT") or (isinstance(tok, tuple) and tok[0] == "TERM"):
                rhs = parse_not()
                val = rhs and val
            else:
                return val

    def parse_not():
        nonlocal pos
        if peek() == ("OP", "NOT"):
            pos += 1
            return not parse_not()
        return parse_atom()

    def parse_atom():
        nonlocal pos
        tok = peek()
        if tok == "(":
            pos += 1
            val = parse_or()
            if peek() == ")":
                pos += 1
            return val
        if isinstance(tok, tuple) and tok[0] == "TERM":
            pos += 1
            return term_matches(tok[1], text)
        return False

    try:
        result = parse_or()
        if pos != len(tokens):
            return False
        return result
    except Exception:
        return False


def paper_text(paper):
    """候选文献用于本地表达式匹配的文本（标题 + 英文摘要 + 概念关键词）"""
    return " ".join([
        paper.get("title", "") or "",
        paper.get("abstract_en", "") or "",
        paper.get("keywords", "") or "",
    ]).lower()


def _beijing_now():
    """runner 时区为 UTC；北京时间 = UTC+8，且无夏令时"""
    return datetime.utcnow() + timedelta(hours=8)


def _plan_day_matches(plan, bj):
    """按北京时间判断「今天该不该跑」（不看时刻）"""
    interval = plan["interval"]
    if interval == "daily":
        return True
    if interval == "weekly":
        wd = plan["weekdays"][0] if plan["weekdays"] else 1  # 1=周一
        return bj.isoweekday() == wd
    if interval == "semimonthly":
        # 每半个月 = 每月月初 1 日 + 月中 15 日（二者恰好相隔 14 天）
        return bj.day in (1, 15)
    if interval == "monthly":
        return bj.day == plan["day_of_month"]
    return False


def is_plan_due(plan, bj):
    """到期 = 今天该跑 且 今天还没跑过 且 已到/过了计划时刻。
    last_run_date 防重（cron 被重试、或晚到的 cron 补跑都不会重复）。"""
    if not _plan_day_matches(plan, bj):
        return False
    if plan["last_run_date"] == bj.strftime("%Y-%m-%d"):
        return False
    return (bj.hour, bj.minute) >= (plan["hour"], plan["minute"])


def _build_plan_tasks(plan, journmap):
    """把一个计划摊成「网络抓取任务」：
    每个（选了且存在的）期刊一个任务；没有期刊但有表达式时，退化为「按关键词检索」一个任务。"""
    tasks = []
    journals = [journmap[jid] for jid in plan["journal_ids"] if jid in journmap]
    if journals:
        for jrn in journals:
            tasks.append({"kind": "journal", "journal": jrn})
    elif plan["expression"]:
        q = build_broad_query(plan["expression"])
        if q:
            tasks.append({"kind": "keyword", "query": q})
    return tasks


def _fetch_tasks(tasks, from_date, to_date):
    """**并发**抓取（线程池，限流防限速）；返回与 tasks 等长的结果列表。
    journal → (papers, via, total)；keyword → list[work]；失败为 None。"""
    results = [None] * len(tasks)
    if not tasks:
        return results
    with ThreadPoolExecutor(max_workers=MAX_FETCH_WORKERS) as ex:
        future_map = {}
        for i, t in enumerate(tasks):
            if t["kind"] == "journal":
                fut = ex.submit(collect_journal_papers, t["journal"], from_date, to_date)
            else:
                fut = ex.submit(search_openalex, t["query"], from_date, to_date, 200)
            future_map[fut] = i
        for fut in as_completed(future_map):
            i = future_map[fut]
            try:
                results[i] = fut.result()
            except Exception as e:
                print(f"[ERROR] 抓取任务失败: {e}")
                results[i] = None
    return results


def _consume_plan(plan, journmap, tasks, fetches, accepted, tag):
    """把抓取结果按计划表达式过滤，命中的放进 accepted；返回 (result, found_any)。
    tasks / fetches 同序，保证日志按计划、按期刊可读。"""
    name = plan["plan_name"] or plan["plan_id"]
    expr = plan["expression"]
    missing = [jid for jid in plan["journal_ids"] if jid not in journmap]
    if missing:
        print(f"[WARN] 计划「{name}」引用了不存在的期刊 id: {', '.join(missing)}")

    result = {"name": name, "expression": expr, "total_found": 0, "new_papers": []}
    found_any = False
    for i, t in enumerate(tasks):
        res = fetches[i]
        if t["kind"] == "journal":
            jrn = t["journal"]
            print(f"\\n[INFO] {tag}「{name}」追踪期刊: {jrn['name']}")
            if res is None:
                print("       来源: error，检索到: 0 篇")
                continue
            papers, via, total = res
            print(f"       来源: {via}，检索到: {total} 篇")
            result["total_found"] += total
            if via == "none":
                continue
            found_any = True
            for paper in papers:
                paper["tracking_group"] = f"{tag}：{name}"
                if expr and not evaluate_expression(expr, paper_text(paper)):
                    continue
                accepted.append({"paper": paper, "plan_name": name})
        else:
            print(f"\\n[INFO] {tag}「{name}」按关键词检索: {expr}")
            works = res or []
            result["total_found"] = len(works)
            found_any = True
            for work in works:
                paper = openalex_to_literature(work, f"{tag}：{name}")
                if evaluate_expression(expr, paper_text(paper)):
                    accepted.append({"paper": paper, "plan_name": name})
    return result, found_any


def run_scheduled(bj):
    """定时追踪：**先探针**（读计划 → 判断到期），不到期直接返回，零网络请求；
    到期则把各计划 / 期刊的抓取任务摊平后**并发**跑（合并成一次 job，但抓取并行）。"""
    print("=" * 60)
    print("AcademicFlow Scheduled Tracking")
    print("=" * 60)
    print(f"[INFO] 北京时间: {bj.strftime('%Y-%m-%d %H:%M:%S')}")

    plans = load_plans()
    due = [p for p in plans if is_plan_due(p, bj)]
    print(f"[INFO] 启用计划 {len(plans)} 个，本次到期 {len(due)} 个")
    if not due:
        print("[INFO] 没有到期计划，跳过（不发任何网络请求）。")
        return 0

    journmap = load_all_journals()
    existing_dois = load_seen_dois()
    print(f"[INFO] 已见过的 DOI 数: {len(existing_dois)}")

    date_str = bj.strftime("%Y-%m-%d")
    from_date = (bj - timedelta(days=7)).strftime("%Y-%m-%d")
    to_date = date_str

    # 把所有到期计划的抓取任务摊平，**并发**抓取（合并成一次 job，但按多路并行）
    plan_tasks = [_build_plan_tasks(p, journmap) for p in due]
    all_tasks = [t for tasks in plan_tasks for t in tasks]
    print(f"[INFO] 并发抓取任务 {len(all_tasks)} 个（{MAX_FETCH_WORKERS} 路并发）")
    fetches = _fetch_tasks(all_tasks, from_date, to_date)

    accepted = []
    plan_results = []
    ran = {}
    cursor = 0
    for plan, tasks in zip(due, plan_tasks):
        sub = fetches[cursor:cursor + len(tasks)]
        cursor += len(tasks)
        result, found_any = _consume_plan(plan, journmap, tasks, sub, accepted, "计划")
        plan_results.append(result)
        if found_any:
            ran[plan["plan_id"]] = date_str

    new_papers = []
    for item in accepted:
        paper = item["paper"]
        doi = paper["doi"].strip().lower()
        if not doi or doi in existing_dois:
            continue
        existing_dois.add(doi)
        new_papers.append(paper)
        for r in plan_results:
            if r["name"] == item["plan_name"]:
                r["new_papers"].append(paper)
                break

    if new_papers:
        print(f"\\n[INFO] 共 {len(new_papers)} 篇候选，写入 tracking/inbox.csv ...")
        append_candidates(new_papers)
    else:
        print("\\n[INFO] 没有新的候选文献。")

    write_log(date_str, plan_results, [], group_label="计划")
    write_plans_last_run(ran)

    print("\\n[INFO] 定时追踪完成。")
    return 0


def run_plan_once(plan_id):
    """立即试跑（手动触发、**一次性**）：只跑指定 id 的单个计划，**不写 last_run_date**。
    与定时追踪共用同一套抓取/过滤管线，只是限定为单计划、且不参与「当天防重」。"""
    print("=" * 60)
    print("AcademicFlow Plan Test Run")
    print("=" * 60)

    plan = load_plan_by_id(plan_id)
    if not plan:
        print(f"[ERROR] 找不到计划 id={plan_id}，请检查 plans.csv。")
        return 1

    bj = _beijing_now()
    name = plan["plan_name"] or plan["plan_id"]
    print(f"[INFO] 试跑计划: {name}（id={plan['plan_id']}）")
    print(f"[INFO] 北京时间: {bj.strftime('%Y-%m-%d %H:%M:%S')}")

    journmap = load_all_journals()
    existing_dois = load_seen_dois()
    print(f"[INFO] 已见过的 DOI 数: {len(existing_dois)}")

    date_str = bj.strftime("%Y-%m-%d")
    from_date = (bj - timedelta(days=7)).strftime("%Y-%m-%d")
    to_date = date_str

    tasks = _build_plan_tasks(plan, journmap)
    print(f"[INFO] 抓取任务 {len(tasks)} 个（{MAX_FETCH_WORKERS} 路并发）")
    fetches = _fetch_tasks(tasks, from_date, to_date)

    accepted = []
    result, _ = _consume_plan(plan, journmap, tasks, fetches, accepted, "试跑")

    new_papers = []
    for item in accepted:
        paper = item["paper"]
        doi = paper["doi"].strip().lower()
        if not doi or doi in existing_dois:
            continue
        existing_dois.add(doi)
        new_papers.append(paper)
        for r in [result]:
            if r["name"] == item["plan_name"]:
                r["new_papers"].append(paper)
                break

    if new_papers:
        print(f"\\n[INFO] 共 {len(new_papers)} 篇候选，写入 tracking/inbox.csv ...")
        append_candidates(new_papers)
    else:
        print("\\n[INFO] 没有新的候选文献。")

    write_log(date_str, [result], [], group_label="计划")
    # 注意：立即试跑是**一次性**验证，不写 last_run_date，不影响定时追踪的防重。
    print("\\n[INFO] 立即试跑完成。")
    return 0


def run_immediate():
    """立即追踪（手动触发、无 plan_id 时）：按当前启用的关键词组 × 期刊跑一次。"""
    bj = _beijing_now()
    print("=" * 60)
    print("AcademicFlow Immediate Tracking")
    print("=" * 60)

    date_str = bj.strftime("%Y-%m-%d")
    from_date = (bj - timedelta(days=7)).strftime("%Y-%m-%d")
    to_date = date_str

    print(f"[INFO] 追踪日期范围: {from_date} ~ {to_date}")

    # 加载关键词组（丢弃空表达式）+ 期刊
    groups = [g for g in load_keyword_groups() if (g.get("expression") or "").strip()]
    journals = load_journals()
    print(f"[INFO] 已启用的关键词组: {len(groups)} 个")
    print(f"[INFO] 已启用的期刊: {len(journals)} 个")
    if not groups and not journals:
        print("[INFO] 没有启用的关键词组或期刊，跳过追踪。")
        return 0

    # 加载已见过的 DOI（文献库 ∪ 候选表）
    existing_dois = load_seen_dois()
    print(f"[INFO] 已见过的 DOI 数: {len(existing_dois)}")

    has_keywords = len(groups) > 0
    has_journals = len(journals) > 0

    # 命中语义：
    #   期刊侧 = 命中「任一」期刊即可（OR）
    #   关键词侧 = 满足「任一」关键词组表达式即可（组间 OR；组内 AND/OR/NOT）
    #   两侧都配了 = 必须（期刊命中）AND（关键词命中）
    #   只配一侧 = 只按那一侧追
    def match_group(text):
        for g in groups:
            if evaluate_expression(g["expression"], text):
                return g
        return None

    group_results = [{
        "id": g["id"],
        "name": g["name"],
        "expression": g["expression"],
        "total_found": 0,
        "new_papers": [],
    } for g in groups]
    journal_results = []
    accepted = []  # {paper, journal_name, group_name}

    # ---------- ① 逐刊搜索（RSS 优先；配了期刊必跑：AND 的期刊侧 / 仅期刊模式的主查询）----------
    if has_journals:
        for jrn in journals:
            print(f"\\n[INFO] 追踪期刊: {jrn['name']}")
            papers, via, total = collect_journal_papers(jrn, from_date, to_date)
            print(f"       来源: {via}，检索到: {total} 篇")
            journal_results.append({
                "id": jrn["id"], "name": jrn["name"],
                "issn": jrn["issn"] or ("RSS" if via == "rss" else ""),
                "via": via, "total_found": total, "new_papers": [],
            })
            if via == "none":
                continue

            for paper in papers:
                paper["tracking_group"] = f"期刊：{jrn['name']}"
                group = None
                if has_keywords:
                    group = match_group(paper_text(paper))
                    if not group:
                        continue  # 配了关键词：期刊命中之后还必须关键词命中（AND）
                if group:
                    for r in group_results:
                        if r["name"] == group["name"]:
                            r["total_found"] += 1
                            break
                accepted.append({
                    "paper": paper,
                    "journal_name": jrn["name"],
                    "group_name": group["name"] if group else None,
                })

            if via == "openalex":
                time.sleep(0.5)

    # ---------- ② 逐组搜索关键词（只配关键词、未配期刊时）----------
    if has_keywords and not has_journals:
        for grp in groups:
            query = build_broad_query(grp["expression"])
            if not query:
                continue
            print(f"\\n[INFO] 搜索关键词组: {grp['name']}")
            print(f"       表达式: {grp['expression']}")
            works = search_openalex(query, from_date, to_date, per_page=200)
            print(f"       检索到: {len(works)} 篇")

            for r in group_results:
                if r["id"] == grp["id"]:
                    r["total_found"] = len(works)
                    break

            for work in works:
                paper = openalex_to_literature(work, grp["name"])
                if evaluate_expression(grp["expression"], paper_text(paper)):
                    accepted.append({
                        "paper": paper,
                        "journal_name": None,
                        "group_name": grp["name"],
                    })

            # OpenAlex 礼貌等待
            time.sleep(0.5)

    # ---------- ③ 去重 + 归集（填日志计数）----------
    new_papers = []
    for item in accepted:
        paper = item["paper"]
        doi = paper["doi"].strip().lower()
        if not doi or doi in existing_dois:
            continue
        existing_dois.add(doi)
        new_papers.append(paper)
        if item["group_name"]:
            for r in group_results:
                if r["name"] == item["group_name"]:
                    r["new_papers"].append(paper)
                    break
        if item["journal_name"]:
            for r in journal_results:
                if r["name"] == item["journal_name"]:
                    r["new_papers"].append(paper)
                    break

    # 写入「候选」（筛选制：等用户在追踪页裁决，**不直接进文献库**）
    if new_papers:
        print(f"\\n[INFO] 共 {len(new_papers)} 篇候选，写入 tracking/inbox.csv ...")
        append_candidates(new_papers)
    else:
        print("\\n[INFO] 没有新的候选文献。")

    # 写日志
    write_log(date_str, group_results, journal_results)

    print("\\n[INFO] 立即追踪完成。")
    return 0


def main():
    """入口：cron 触发走「计划」路径；
    手动触发时若带 plan_id → 立即试跑该计划（一次性），否则走常规立即追踪。"""
    if (os.environ.get("TRIGGER_EVENT", "") or "").strip() == "schedule":
        return run_scheduled(_beijing_now())
    plan_id = (os.environ.get("TRIGGER_PLAN_ID", "") or "").strip()
    if plan_id:
        return run_plan_once(plan_id)
    return run_immediate()


if __name__ == "__main__":
    sys.exit(main())
`

const MONTHLY_CLEANUP_YML = `# AcademicFlow monthly PDF cleanup workflow
# 每月1日自动清理一个月前上传的PDF文件，仅保留Markdown
name: Monthly PDF Cleanup

on:
  workflow_dispatch:
  schedule:
    - cron: '0 2 1 * *'

jobs:
  cleanup:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout
        uses: actions/checkout@v4

      - name: Cleanup old PDFs
        run: |
          echo "=== AcademicFlow PDF Monthly Cleanup ==="
          echo "Looking for PDFs older than 30 days..."
          
          # 查找 literatures 和 textbooks 目录下超过30天的PDF
          find literatures textbooks -name "*.pdf" -type f -mtime +30 2>/dev/null | while read -r pdf; do
            if [ -f "$pdf" ]; then
              # 检查对应的Markdown是否存在
              md_file="\${pdf%.pdf}.md"
              md_dir="\${pdf%.pdf}"
              
              if [ -f "$md_file" ] || [ -d "$md_dir" ]; then
                echo "Removing old PDF: $pdf"
                git rm "$pdf"
              else
                echo "Keeping $pdf (no Markdown counterpart found)"
              fi
            fi
          done
          
          echo "Cleanup complete."

      - name: Commit and push if changes
        run: |
          git config user.name "academicflow-bot"
          git config user.email "bot@academicflow.local"
          
          if git diff --cached --quiet; then
            echo "No old PDFs to remove."
          else
            git commit -m "chore: monthly cleanup - remove PDFs older than 30 days"
            git push
            echo "Cleanup committed and pushed."
          fi
`

